import{Z as t,e as r,f as o,a0 as s}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Reports","description":"","frontmatter":{},"headers":[],"relativePath":"reports/reports.md","filePath":"reports/reports.md","lastUpdated":null}'),a={name:"reports/reports.md"};function n(d,e,i,l,p,h){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a getting-started walkthrough, see <a href="/guides/submissions-workflows/saved-reports-and-scheduled-delivery">Saved reports and scheduled delivery</a>.</p></div><p>Reports are saved analytical views over Formie submissions. Use them when the submissions index is too operational — review, edit, change status — and you need answers like “how many enquiries came in last week, by form, excluding spam?” without exporting by hand each time.</p><p>Open <strong>Formie → Reports</strong> to create and run reports. Report definitions sync through <a href="https://craftcms.com/docs/5.x/system/project-config.html" target="_blank" rel="noreferrer">project config</a>, so filters, columns, and display settings deploy with your Craft project.</p><h2 id="what-a-report-includes" tabindex="-1">What a Report Includes <a class="header-anchor" href="#what-a-report-includes" aria-label="Permalink to &quot;What a Report Includes&quot;">​</a></h2><p>Each report combines:</p><table tabindex="0"><thead><tr><th>Area</th><th>What it controls</th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Name, handle, and which forms are included</td></tr><tr><td><strong>Filters</strong></td><td>Date windows (new reports default to the last month), complete/incomplete/spam, statuses, and more</td></tr><tr><td><strong>Columns</strong></td><td>Which submission attributes and fields appear in the table and export</td></tr><tr><td><strong>Display</strong></td><td>Chart type and summary layout on the report run screen</td></tr><tr><td><strong>Export</strong></td><td>Export filename pattern (with variable tokens)</td></tr><tr><td><strong>Scheduled</strong></td><td>Links to <a href="/reports/scheduled-reports">scheduled email delivery</a> for this report</td></tr></tbody></table><p>Running a report shows summary counts, a trend chart, and a paginated submissions table. <strong>Export</strong> downloads submission data using the report’s current filters and column settings.</p><h2 id="export-formats" tabindex="-1">Export Formats <a class="header-anchor" href="#export-formats" aria-label="Permalink to &quot;Export Formats&quot;">​</a></h2><p>From the report run screen, choose <strong>Export</strong> and pick a file type:</p><table tabindex="0"><thead><tr><th>Format</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>Excel</strong> (<code>.xlsx</code>)</td><td>Spreadsheets and sharing with non-technical teams</td></tr><tr><td><strong>CSV</strong> (<code>.csv</code>)</td><td>Universal tabular import</td></tr><tr><td><strong>JSON</strong> (<code>.json</code>)</td><td>Feeds and developer tooling</td></tr><tr><td><strong>XML</strong> (<code>.xml</code>)</td><td>Structured interchange</td></tr><tr><td><strong>Text</strong> (<code>.txt</code>)</td><td>Plain tab-separated output</td></tr></tbody></table><p>The file extension is added automatically from the format you choose. The <strong>Export Filename</strong> setting on the report editor controls the basename only — not the extension.</p><p><a href="/reports/scheduled-reports">Scheduled reports</a> attach exports in the <strong>File Type</strong> you choose on each schedule (CSV, Excel, JSON, XML, or text). That uses the same export engine as on-demand downloads.</p><h2 id="large-exports" tabindex="-1">Large Exports <a class="header-anchor" href="#large-exports" aria-label="Permalink to &quot;Large Exports&quot;">​</a></h2><p>Reports with more submissions than the <strong>Report Async Export Row Threshold</strong> (<strong>Settings → Submissions</strong>, default <strong>1000</strong>) are exported in the background via Craft’s queue. The control panel shows an <strong>Exporting…</strong> state while the export runs, and your download starts automatically when it is ready. If you leave the control panel before it finishes, a backup email with a download link is sent to your account email address when Craft’s mailer is configured.</p><p>All export formats write rows incrementally to disk, including Excel, JSON and XML. Formie records the matching submission IDs before exporting so new submissions cannot shift rows between batches. Field values are read as each batch is processed; submissions that are deleted or no longer match the filters are omitted. Scheduled reports still attach small exports to the summary email; when an export exceeds the <strong>Maximum Email Attachment Size</strong> (<strong>Settings → Notifications</strong>), the email includes a signed download link instead.</p><p>If a queue worker stops during an export, retry the failed job in Craft’s queue. The retry rebuilds the unfinished file and removes abandoned spreadsheet parts. Completed exports retain their existing download links when a job is repeated. If the backup email fails, the completed file remains available in the control panel.</p><p>Download links expire after <strong>Report Interactive Export Expiry</strong> or <strong>Report Scheduled Export Expiry</strong> (<strong>Settings → Submissions</strong>, defaults 72 and 48 hours). <strong>Single-Use Report Export Downloads</strong> is enabled by default so each signed email link works once; control panel auto-downloads use a separate authenticated route and do not invalidate email links.</p><h2 id="reports-vs-the-submissions-index" tabindex="-1">Reports vs the Submissions Index <a class="header-anchor" href="#reports-vs-the-submissions-index" aria-label="Permalink to &quot;Reports vs the Submissions Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Submissions index</th><th>Reports</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Day-to-day submission management</td><td>Saved analysis and recurring output</td></tr><tr><td><strong>Filters</strong></td><td>Per-session element index filters</td><td>Saved, reusable filter sets</td></tr><tr><td><strong>Export</strong></td><td>Not available (use reports instead)</td><td>On-demand export in multiple formats</td></tr><tr><td><strong>Email delivery</strong></td><td>—</td><td><a href="/reports/scheduled-reports">Scheduled reports</a> (configurable file type)</td></tr></tbody></table><p>If you only need a one-off file, run a report and export in the format you need. If you need the same view every Monday morning, save the report and attach a scheduled delivery.</p><h2 id="export-filename" tabindex="-1">Export Filename <a class="header-anchor" href="#export-filename" aria-label="Permalink to &quot;Export Filename&quot;">​</a></h2><p>On the report editor <strong>Export</strong> tab, set <strong>Export Filename</strong> to control the basename for downloads and scheduled attachments.</p><p>The default pattern is <code>formie-report-{handle}-{timestamp}</code>. Use the variable picker to insert tokens such as:</p><ul><li><code>{name}</code> and <code>{handle}</code> — report title and handle</li><li><code>{timestamp}</code> — current date and time when the file is generated</li><li>General and site tokens from the same picker used elsewhere in Formie</li></ul><p>Tokens are resolved when the export runs, not when you save the report.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Reports use dedicated Craft user permissions:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Allows</th></tr></thead><tbody><tr><td><strong>Access reports</strong></td><td>View the Reports section and run saved reports</td></tr><tr><td><strong>Manage reports</strong></td><td>Create, edit, and delete reports; export data</td></tr><tr><td><strong>Manage scheduled reports</strong></td><td>Configure scheduled email delivery under <strong>Settings → Scheduled Reports</strong> and on a report’s <strong>Scheduled</strong> tab</td></tr></tbody></table><p>Users with <strong>Export submissions</strong> can also export from reports without full manage access.</p><h2 id="project-config" tabindex="-1">Project Config <a class="header-anchor" href="#project-config" aria-label="Permalink to &quot;Project Config&quot;">​</a></h2><p>Report settings are stored under <code>formie.reports.{uid}</code> in project config. Scheduled delivery settings (recipients, schedule, email content) are stored under <code>formie.scheduledReports.{uid}</code>.</p><p>Database-only fields such as <code>lastSentAt</code> live in the database and are not synced through project config.</p>',33)])])}const m=t(a,[["render",n]]);export{u as __pageData,m as default};
